<template>
  <view class="page">
    <view class="status-spacer" :style="{ height: `${statusBarHeight}px` }" />
    <view class="nav-bar">
      <image class="nav-back" :src="arrowLeftIcon" mode="aspectFit" @click="goBack" />
      <text class="nav-title">账户充值</text><view class="nav-space" />
    </view>
    <scroll-view scroll-y class="content">
      <view class="balance-hero"><text class="balance-label">当前余额（元）</text><text class="balance-value"><text>¥</text>{{ money(balance) }}</text><text class="balance-tip">充值后可用于支付零工报酬、购买积分等</text></view>
      <view class="promo-row"><view class="promo-item"><text class="promo-badge">充</text><text>充得多送得多</text></view><view class="promo-item"><text class="promo-badge">安</text><text>资金安全保障</text></view><view class="promo-item"><text class="promo-badge">快</text><text>秒到账</text></view></view>
      <view class="section-card"><text class="section-title">选择充值金额</text><view class="amount-grid"><view v-for="item in amounts" :key="item.amount" class="amount-option" :class="{ active: selectedAmount === item.amount && !customAmount }" @click="selectAmount(item.amount)"><text class="amount-num">¥ {{ formatInteger(item.amount) }}</text><text v-if="item.bonus" class="amount-bonus">送 {{ item.bonus }} 元</text></view></view><view class="custom-row"><text class="custom-label">自定义</text><text class="custom-yuan">¥</text><input v-model="customAmount" type="digit" class="custom-input" placeholder="请输入充值金额" @input="onCustomInput" /></view></view>
      <view class="section-card"><text class="section-title">选择支付方式</text><view class="pay-item active"><view class="pay-left"><view class="pay-icon wechat"><image :src="wechatIcon" mode="aspectFit" /></view><text class="pay-name">微信支付</text></view><view class="pay-check"><view /></view></view><view class="pay-item disabled"><view class="pay-left"><view class="pay-icon bank"><image :src="bankIcon" mode="aspectFit" /></view><text class="pay-name">企业银行账户</text></view><view class="pay-check" /></view></view>
      <button class="recharge-btn" :disabled="submitting" @click="submitRecharge">{{ submitting ? '处理中...' : `立即充值 ¥${money(payAmount)}` }}</button>
      <text class="payment-tip">微信收银台完成支付后，以后端支付结果和实际入账为准</text><view class="safe-space" />
    </scroll-view>
  </view>
</template>

<script setup>
import { computed, ref } from 'vue'
import { onLoad, onUnload } from '@dcloudio/uni-app'
import { createBossWalletWechatRecharge, getBossBalance, getBossWalletRechargeResult } from '@/api/backend'
import arrowLeftIcon from '/static/icons/boss-points/arrow-left-dark.svg'
import wechatIcon from '/static/icons/worker-points-withdraw/weixin-white.svg'
import bankIcon from '/static/icons/boss-recharge/building-columns-white.svg'

const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 0
const balance = ref(0); const selectedAmount = ref(2000); const customAmount = ref(''); const submitting = ref(false); const idempotencyKey = ref(''); let timer = null
const amounts = [{ amount: 500 }, { amount: 1000, bonus: 30 }, { amount: 2000, bonus: 80 }, { amount: 5000, bonus: 260 }, { amount: 10000, bonus: 600 }, { amount: 20000, bonus: 1400 }]
const payAmount = computed(() => customAmount.value === '' ? selectedAmount.value : Number(customAmount.value) || 0)
onLoad(loadBalance); onUnload(() => { if (timer) clearTimeout(timer) })
async function loadBalance() { try { const result = await getBossBalance(); const data = result?.data ?? result ?? {}; const yuan = Number(data.balanceYuan); const fen = Number(data.balanceFen ?? data.balance ?? 0); balance.value = Number.isFinite(yuan) ? yuan : (Number.isFinite(fen) ? fen / 100 : 0) } catch (_) {} }
function selectAmount(value) { selectedAmount.value = value; customAmount.value = ''; idempotencyKey.value = '' }
function onCustomInput(event) { const value = String(event?.detail?.value || '').replace(/[^\d.]/g, ''); const dot = value.indexOf('.'); customAmount.value = dot < 0 ? value : `${value.slice(0, dot)}.${value.slice(dot + 1).replace(/\./g, '').slice(0, 2)}`; idempotencyKey.value = '' }
async function submitRecharge() { const amount = Number(payAmount.value); if (!/^\d+(\.\d{1,2})?$/.test(String(payAmount.value)) || amount < 0.01) { uni.showToast({ title: '充值金额不能低于0.01元', icon: 'none' }); return } if (submitting.value) return; submitting.value = true; try { if (!idempotencyKey.value) idempotencyKey.value = `boss-recharge-${Date.now()}-${Math.random().toString(36).slice(2)}`; const order = await createBossWalletWechatRecharge({ amount: Number(amount.toFixed(2)) }, idempotencyKey.value); const payParams = order?.payParams || {}; if (!order?.orderNo || !payParams.package) throw new Error('微信支付参数无效'); /* #ifdef MP-WEIXIN */ await new Promise((resolve, reject) => uni.requestPayment({ provider: 'wxpay', timeStamp: String(payParams.timeStamp), nonceStr: String(payParams.nonceStr), package: String(payParams.package), signType: String(payParams.signType || 'RSA'), paySign: String(payParams.paySign), success: resolve, fail: reject })); /* #endif */ uni.showToast({ title: '支付结果确认中', icon: 'none' }); poll(order.orderNo) } catch (error) { uni.showToast({ title: /cancel/i.test(String(error?.errMsg || error?.message)) ? '支付已取消' : String(error?.message || '充值失败'), icon: 'none' }) } finally { submitting.value = false } }
function poll(orderNo) { let count = 0; const check = async () => { try { const order = await getBossWalletRechargeResult(orderNo); const status = String(order?.status || '').toUpperCase(); if (['PAID', 'SUCCESS', '支付成功'].includes(status)) { uni.showToast({ title: '充值成功', icon: 'success' }); await loadBalance(); return } } catch (_) {} if (++count < 15) timer = setTimeout(check, 2000) }; check() }
function money(value) { return Number(value || 0).toFixed(2) }; function formatInteger(value) { return Number(value).toLocaleString('zh-CN') }; function goBack() { uni.navigateBack() }
</script>

<style scoped>
.page{display:flex;flex-direction:column;height:100vh;overflow:hidden;background:#f3f4f6}.status-spacer,.nav-bar{flex-shrink:0;background:#fff}.nav-bar{position:relative;display:flex;align-items:center;justify-content:space-between;height:100rpx;padding:0 32rpx;box-sizing:border-box}.nav-back,.nav-space{width:40rpx;height:40rpx}.nav-title{position:absolute;left:50%;color:#333;font-size:34rpx;font-weight:600;transform:translateX(-50%)}.content{flex:1;min-height:0}.balance-hero{margin:24rpx 32rpx;padding:44rpx 40rpx;border-radius:32rpx;background:linear-gradient(135deg,#ffe8b0,#ffd96f);box-shadow:0 8rpx 32rpx rgba(255,180,100,.2)}.balance-label,.balance-value,.balance-tip{display:block;color:#8b4513}.balance-label{font-size:24rpx}.balance-value{margin-top:12rpx;font-size:68rpx;font-weight:800}.balance-value text{margin-right:4rpx;font-size:36rpx}.balance-tip{margin-top:20rpx;color:#a0522d;font-size:22rpx}.promo-row{display:flex;justify-content:space-around;padding:0 32rpx 28rpx}.promo-item{display:flex;flex-direction:column;align-items:center;color:#999;font-size:20rpx}.promo-badge{display:flex;align-items:center;justify-content:center;width:56rpx;height:56rpx;margin-bottom:8rpx;border-radius:50%;color:#ff6b35;background:#ffe8b0;font-weight:700}.section-card{margin:0 32rpx 24rpx;padding:32rpx;border-radius:28rpx;background:#fff;box-shadow:0 2rpx 12rpx rgba(0,0,0,.04)}.section-title{display:block;margin-bottom:24rpx;color:#333;font-size:26rpx;font-weight:600}.amount-grid{display:flex;flex-wrap:wrap;gap:20rpx}.amount-option{display:flex;flex-direction:column;align-items:center;justify-content:center;width:calc((100% - 40rpx)/3);min-height:104rpx;border:3rpx solid #eee;border-radius:20rpx;background:#f9fafb;box-sizing:border-box}.amount-option.active{border-color:#ff6b35;background:#fff3e6}.amount-num{color:#333;font-size:28rpx;font-weight:700}.amount-option.active .amount-num{color:#ff6b35}.amount-bonus{margin-top:6rpx;color:#ff6b35;font-size:20rpx}.custom-row{display:flex;align-items:center;gap:14rpx;margin-top:28rpx;padding-top:28rpx;border-top:1rpx solid #f5f5f5}.custom-label{color:#666;font-size:26rpx}.custom-yuan{color:#333;font-size:32rpx;font-weight:700}.custom-input{flex:1;min-width:0;font-size:34rpx;font-weight:700}.pay-item{display:flex;align-items:center;justify-content:space-between;padding:20rpx 0;border-bottom:1rpx solid #f5f5f5}.pay-item:last-child{border-bottom:0}.pay-item.disabled{opacity:.5}.pay-left{display:flex;align-items:center;gap:20rpx}.pay-icon{display:flex;align-items:center;justify-content:center;width:64rpx;height:64rpx;border-radius:16rpx}.pay-icon image{width:38rpx;height:38rpx}.pay-icon.wechat{background:#07c160}.pay-icon.bank{background:#1677ff}.pay-name{color:#333;font-size:26rpx}.pay-check{display:flex;align-items:center;justify-content:center;width:36rpx;height:36rpx;border:3rpx solid #ddd;border-radius:50%;box-sizing:border-box}.pay-item.active .pay-check{border-color:#ff6b35;background:#ff6b35}.pay-check view{width:12rpx;height:12rpx;border-radius:50%;background:#fff}.recharge-btn{width:calc(100% - 64rpx);height:92rpx;margin:16rpx 32rpx 0;border:0;border-radius:46rpx;color:#fff;background:linear-gradient(135deg,#ff8c5a,#ff6b35);box-shadow:0 8rpx 32rpx rgba(255,107,53,.3);font-size:30rpx;font-weight:600;line-height:92rpx}.recharge-btn::after{border:0}.recharge-btn[disabled]{opacity:.6}.payment-tip{display:block;margin:20rpx 32rpx 0;color:#999;font-size:21rpx;text-align:center}.safe-space{height:calc(32rpx + env(safe-area-inset-bottom))}
</style>
